"""Render the ordered Apple remaining-issue run from retained stage workpapers."""
from pathlib import Path
from decimal import Decimal as D
from html import escape as h
import json
ROOT=Path(__file__).resolve().parents[1];R=ROOT/'docs/company-resolutions/AAPL/remaining-issues-2026-11-04'
def load(name):return json.loads((R/name).read_text())
def bn(x):return 'Unresolved' if x is None else f'{D(x)/D(10**9):,.3f}B'
def table(headers,rows):return '<div class="scroll"><table><thead><tr>'+''.join('<th>'+h(x)+'</th>' for x in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td data-label="'+h(label,quote=True)+'">'+str(x)+'</td>' for label,x in zip(headers,row,strict=True))+'</tr>' for row in rows)+'</tbody></table></div>'
p=load('platform-resolution.json');f=load('financing/results.json');da=load('da/results.json');tax=load('tax/results.json');eq=load('equity/results.json')
old=json.loads((R.parent/'operating-fcff-2026-11-04/adopted-history.json').read_text());a=p['anchor_support']
labels={'EVIDENCE_BLOCKED':'Issuer evidence still required','AGGREGATE_ADOPTED_RECONCILIATION_OPEN':'Reported aggregate adopted; exact reconciliation open','POLICY_ADOPTED':'Policy adopted under latest approval','PARTIAL_SOURCE_BOUND':'Dated inputs bound; full valuation open'}
sections=[]
sections.append('<h2>Decisions and current outcome</h2>'+table(['Stage','Applied treatment','Result'],[[s['label'],h(s['detail']),labels[s['outcome']]] for s in p['stages']]))
sections.append('<h2>Five-year financial amounts are preserved</h2>'+table(['Fiscal year','Standardized FCFF','Identified-funding FCFE','Exact full FCFE'],[['FY'+str(x['fiscal_year']),bn(old['periods'][i]['fcff']['amount_usd']),bn(x['identified_funding_fcfe']['amount_usd'])+' · provisional','Unresolved'] for i,x in enumerate(f['periods'])])+'<p>FCFF uses the existing operating-income/reported-tax/current-NWC/cash-PP&E definition. The financing review does not change any amount, substitute a lease liability for cash paid, or promote identified funding into complete financing coverage. Original CFO-based history and its two interest gaps remain preserved separately.</p>')
sections.append('<h2>1. Financing: exact statements, unresolved composition</h2><p>The five original financing statements reconcile exactly. Known term-debt and commercial-paper cash is counted once; common-stock issuance, buybacks, dividends and award withholding do not become net borrowing. The FY2021 presentation bridge is preserved without an FCFE change. Other financing remains −129/−160/−581/−361/−111M across FY2021–25.</p><p>The existing evidence does not identify the gross components of Other or actual finance-lease principal and its parent cash-flow caption. No component is assumed zero. A small net Other figure is not a defensible bound on unknown offsetting gross cash flows. Current/noncurrent liability shifts, prospective maturities and noncash ROU additions are not realized principal payments.</p><p><strong>Next required evidence:</strong> Apple consolidated annual cash-principal figures and the captions containing them; gross Other-financing decomposition. <a href="financing/issuer-evidence-request.txt">The exact issuer request is prepared and UNSENT</a>. No message has been sent. A complete supported roll-forward is an alternative; it cannot omit noncash modifications/FX or guess additions.</p><p><a href="financing/README.md">Financing workpaper and replay</a> · <a href="financing/financing-classifications.csv">Transaction classification table</a></p>')
sections.append('<h2>2. D&A: a population difference, not a balancing adjustment</h2>'+table(['FY2024 observation','Amount'],[['Cash-statement combined D&A','11.445B'],['Later-note PP&E depreciation','8.2B · rounded'],['Later-note intangible amortization','3.6B · rounded'],['Nominal note total less combined line','0.355B']])+'<p>The source periods agree. Even conservative displayed rounding leaves an unexplained difference of254.5M–455.5M. The later notes distinguish owned/licensed intangible assets and finance-lease PP&E, but supply no numerical reconciliation showing which difference belongs where. Those categories are investigation clues, not an adopted explanation.</p><p><strong>Applied:</strong> retain combined reported D&A for every historical year; add zero plug. No duplicate lease amortization or principal deduction. A diagnostic-only355M extra add-back would move FY2024 to'+bn(da['diagnostic_only']['fcff_if_other_inputs_held_fixed_usd'])+' if everything else stayed fixed. It is neither adopted FCFF nor a forecast; related cash investment/population alignment has not been established.</p><p><a href="da/README.md">D&A source/rounding review</a> · <a href="https://www.sec.gov/Archives/edgar/data/320193/000032019326000026/aapl-20260926.htm">Apple comparative Notes5–6</a></p>')
bridges=tax['forecast_bridges'];brows=[]
for b in bridges:
 q=b['algebraic_component_bridge'];label=b.get('label',b.get('scenario',b.get('case_label','Scenario')));brows.append([label,bn(q['historical_fcff_usd']),bn(q['forecast_fcff_usd']),bn(q['fcff_change_usd']),'Pass · serialization precision only'])
sections.append('<h2>3. Tax and working capital: approved policies, separate populations</h2><p>The latest approval now records the all-year current-tax-inclusive historical NWC convention. It is no longer pending a second manual approval. Current taxes and mixed Other remain in one declared aggregate population across all years; the early-year current-tax splits remain unknown. The materially observable effects stay visible: current tax accrual increases contribute+17.782B in FY2024 and the reversal−13.585B in FY2025 versus tax-excluded diagnostics. This is not an exact unlevered cash-tax reconstruction.</p><p>Five provision/current/deferred/cash-tax schedules and the State Aid/escrow commentary are retained separately. No accounting charge is automatically added back to reported cash, and no broad payable movement is asserted to be entirely the State Aid settlement.</p><p>Forward tax remains an explicitly assumed18%→20% path, with independent terminal20%. Base working capital starts from5% of incremental sales, converted to full-revenue cash needs. Bear/Bull retain Base WC/revenue ratios under the existing scenario policy, so their effective incremental-sales coefficients differ (about5.6060%/4.5272% in the first year). These are assumptions rather than Apple-reported sustainable rates or operating-cash figures.</p>'+table(['Case','FY2025 historical FCFF','FY2026 first forecast','Change','Component bridge'],brows)+'<p>Signed EBIT, tax, D&A, investment and WC differences reconcile each bridge. They include the business/year change and different modeling bases. Tiny decimal serialization differences below1e−30USD are recorded separately, never used as cash adjustments. An algebraic identity is not a complete economic-classification bridge; no cross-basis FCFF CAGR or automatic historical calibration is enabled.</p><p><a href="tax/README.md">Tax source schedules, component bridges and scenario treatment</a></p>')
sections.append('<h2>4. Equity/share review: dated source support, no missing-claim waiver</h2>'+table(['Observation at2025-09-27','Amount','Meaning'],[['Cash and marketable securities',bn(a['cash_and_securities_usd']),'Gross liquidity subtotal; eligibility/reserves not yet resolved'],['Named CP and term debt, carrying',bn(a['named_debt_carrying_usd']),'Not a complete financing-claim value'],['Term-debt disclosed fair value',bn(a['term_debt_fair_value_usd']),'Alternative to term carrying90.678B; rounded source precision retained'],['Finance-lease liability',bn(a['finance_lease_liability_usd']),'Separate from operating-lease service policy and historical principal cash'],['Ordinary common shares',f'{int(a["dated_common_shares"]):,}','Date-matched source population; not EPS-weighted shares'],['Unvested RSUs','151,574,000','Not automatically added to the denominator']])+'<p>The anchor-date common population is selected as denominator support; later cover shares do not replace it. Market-debt fair value, carrying value and face principal are alternative measures, not additional claims to sum. Cash eligibility and claims overlap still require review. A tax-uncertainty or legal provision is not automatically a separate deduction if its cash effects already reside in forecasts.</p><p>Future SBC stays expensed. Pre-anchor award rights require a non-overlapping service/vesting/forfeiture/withholding/settlement treatment. Grant-date award values are not current economic fair values; unrecognized future service cost is not a direct award-value deduction. No automatic RSU addition, no zero omitted-claim assumption and no certified value/share is published.</p><p>FCFF uses matching WACC and a reviewed equity bridge; FCFE uses matching cost of equity without a second debt subtraction. Equal share values are not asserted until financing, tax, investment, timing and ownership assumptions align.</p><p><a href="equity/README.md">Dated source review and reproducible measurement alternatives</a></p>')
validation=load('validation.json') if (R/'validation.json').exists() else {'status':'Independent review and final validation in progress'}
sections.append('<h2>Independent and platform verification</h2><pre>'+h(json.dumps(validation,indent=2))+'</pre><p><a href="independent-review/README.md">Independent audit</a> · <a href="browser-results.json">Live browser receipt</a> · <a href="approval.json">Approval scope</a> · <a href="platform-resolution.json">Pinned platform record</a></p><p>The private platform shows these decisions in a collapsed Apple review panel on the Cash flows tab. The old strict-review issue list is preserved as legacy context; the current list no longer calls missing legacy interest a gap in the selected FCFF method, or asks for approval of the now-adopted tax convention.</p>')
sections.append('<h2>What is still required before Apple can be marked complete</h2><ol>'+''.join('<li>'+h(x)+'</li>' for x in p['remaining_evidence'])+'</ol><p>The implementation stages and passing software checks do not replace the missing financial evidence. Exact historical FCFE and fully reviewed fair value/share cannot be certified from the present packet. The issuer request is ready; obtaining the relevant disclosure or a supported response is the next dependency.</p>')
css="body{margin:0;background:#f1f5f7;color:#193b4e;font:16px/1.6 system-ui,sans-serif}main{max-width:1240px;margin:auto;padding:36px 24px 70px}h1{font:46px/1.14 Georgia,serif;margin:12px 0 20px}h2{font:28px/1.25 Georgia,serif;margin:0 0 18px}.eyebrow{font-size:12px;text-transform:uppercase;letter-spacing:.13em}.verdict{padding:20px;border-left:4px solid #aa862d;background:#fbf5e9}section{background:white;border:1px solid #dbe4ea;padding:26px;border-radius:10px;margin:20px 0}.scroll{overflow:auto}table{width:100%;border-collapse:collapse;font-size:14px;font-variant-numeric:tabular-nums}th,td{padding:12px;text-align:left;border-bottom:1px solid #dbe4ea;vertical-align:top}th{background:#f2f6f9}a{color:#295e78}pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:13px}li{margin:10px 0}@media(max-width:650px){main{padding:24px 12px}h1{font-size:34px}section{padding:18px 14px}.scroll{overflow:visible}table,tbody,tr,td{display:block;width:auto}thead{display:none}tr{padding:10px 0;border-bottom:1px solid #dbe4ea}td{padding:7px 0;border:0}td::before{content:attr(data-label);display:block;font-size:11px;font-weight:700;letter-spacing:.04em;color:#647587;margin-bottom:2px}}"
page='<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="Content-Security-Policy" content="default-src \'none\'; style-src \'unsafe-inline\'; base-uri \'none\'; form-action \'none\'"><title>Apple remaining-issue implementation review</title><style>'+css+'</style></head><body><main><header><div class="eyebrow">Apple · FY2021–FY2025 · November4,2026</div><h1>Apple review remains open</h1><div class="verdict"><strong>Four ordered treatment stages executed; full financial clearance is not established.</strong> The historical tax convention is adopted, dated share/debt support is bound, and the platform exposes the decisions. Exact financing composition, D&A expense reconciliation and complete equity/award treatment remain unresolved. No missing amount is invented and no provisional number is relabeled verified.</div></header>'+''.join('<section>'+s+'</section>' for s in sections)+'</main></body></html>'
# Improve numerical prose spacing while leaving all retained source workpapers unchanged.
for x,y in {'difference of254.5':'difference of 254.5','diagnostic-only355':'diagnostic-only 355','at2025':'at 2025','carrying90.678':'carrying 90.678','assumed18%':'assumed 18%','terminal20%':'terminal 20%','from5%':'from 5%','about5.6060':'about 5.6060','below1e':'below 1e','Notes5':'Notes 5','November4,2026':'November 4, 2026'}.items():page=page.replace(x,y)
